import {authProvider,layoutRepository,createSaveQueue} from './auth-client.js';
const $=s=>document.querySelector(s);let register=false,busy=false,queue=null;
function message(text){$('#authError').textContent=text}function setBusy(value){busy=value;$('#authSubmit').disabled=value;$('#authSwitch').disabled=value;$('#authSubmit').innerHTML=value?'Please wait…':register?'Create account <span>→</span>':'Log in <span>→</span>'}
async function enter(user){const document=await layoutRepository.load();window.wsmsSession={user,document};queue=createSaveQueue(layoutRepository,(status,error)=>{const saved=$('#saved');saved.textContent=status==='saved'?'Saved':status==='error'?'Not saved — click to retry':status==='saving'?'Saving…':'Unsaved changes';saved.classList.toggle('saveError',status==='error');saved.title=error?.message||'';});window.wsmsSaveLayout=document=>queue.schedule(document);$('#accountEmail').textContent=user.email;$('#accountDropdownEmail').textContent=user.email;$('#authLanding').hidden=true;$('#application').hidden=false;await import('./app.js');requestAnimationFrame(()=>window.dispatchEvent(new Event('resize')));if(!document&&['5','4','3','2','1'].some(v=>localStorage.getItem('warehouse-studio-v'+v)))$('#legacyNotice').hidden=false;}
$('#authSwitch').onclick=()=>{if(busy)return;register=!register;message('');$('#authTitle').textContent=register?'Create your workspace':'Log in to your workspace';$('#authSubtitle').textContent=register?'Start planning your warehouse with a free account.':'Your layouts, floors and capacity — all in one place.';$('#confirmLabel').hidden=!register;$('#confirmPassword').required=register;$('#authPassword').autocomplete=register?'new-password':'current-password';$('#authSwitchText').textContent=register?'Already have an account?':'New to WSMS?';$('#authSwitch').textContent=register?'Log in':'Create an account';setBusy(false);};
$('#authForm').onsubmit=async e=>{e.preventDefault();if(busy)return;message('');const email=$('#authEmail').value.trim(),password=$('#authPassword').value;if(register&&password!==$('#confirmPassword').value){message('Passwords do not match.');return}setBusy(true);try{const user=await (register?authProvider.register(email,password):authProvider.login(email,password));await enter(user);$('#authPassword').value='';$('#confirmPassword').value=''}catch(error){message(error.message)}finally{setBusy(false)}};
$('#accountButton').onclick=()=>{const open=$('#accountDropdown').hidden;$('#accountDropdown').hidden=!open;$('#accountButton').setAttribute('aria-expanded',String(open))};document.addEventListener('click',e=>{if(!e.target.closest('.accountMenu')){$('#accountDropdown').hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#accountDropdown').hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});
$('#logoutButton').onclick=async()=>{const b=$('#logoutButton');b.disabled=true;try{await queue?.flush();await authProvider.logout();location.reload()}catch(e){$('#saved').textContent='Could not log out: '+e.message}finally{b.disabled=false}};$('#saved').onclick=()=>queue?.flush().catch(()=>{});$('#importLegacy').onclick=()=>{if(window.wsmsLoadLegacy?.())$('#legacyNotice').hidden=true};$('#dismissLegacy').onclick=()=>{$('#legacyNotice').hidden=true};window.addEventListener('beforeunload',e=>{if(queue?.dirty){e.preventDefault();e.returnValue=''}});
(async()=>{setBusy(true);try{const user=await authProvider.currentUser();await enter(user)}catch(e){if(e.status!==401)message(e.message)}finally{setBusy(false)}})();
